### REQ-INT-LENS-002-002: Interactive Flow Diagrams

**Status**: Approved

**Rationale**: Interactive visualizations enable exploration and understanding of complex data flows, supporting troubleshooting, impact analysis, and collaborative problem-solving.

**Configuration**:

```yaml
# Lenses visualization configuration
lenses:
  visualization:
    enabled: true

    # Flow diagram settings
    diagrams:
      auto_layout: force_directed      # Layout algorithm: force_directed, hierarchical, radial
      max_nodes: 500                   # Maximum nodes to display
      max_edges: 1000                  # Maximum edges to display
      refresh_interval: 30s            # Diagram refresh frequency

      # Interaction capabilities
      interactions:
        zoom_enabled: true
        pan_enabled: true
        node_selection: true
        multi_select: true
        context_menus: true
        tooltips: true

      # Filtering options
      filters:
        by_domain: true                # Filter by business domain
        by_team: true                  # Filter by owning team
        by_sensitivity: true           # Filter by data sensitivity
        by_status: true                # Filter by topic status
        by_message_rate: true          # Filter by throughput

      # Search capabilities
      search:
        enabled: true
        fuzzy_match: true
        regex_support: true
        field_search: true             # Search within field names
        metadata_search: true          # Search metadata properties

      # Export formats
      export:
        png: true
        svg: true
        graphml: true                  # For Neo4j import
        json: true                     # For programmatic access
        pdf: true                      # For documentation

    # Custom visualizations
    custom_dashboards:
      enabled: true
      d3js_support: true
      embedding_enabled: true
      api_access: true
```

**Implementation Details**:

**D3.js Custom Visualization**:
```javascript
// D3.js-based custom lineage visualization
import * as d3 from 'd3';

class LineageVisualization {
    constructor(containerId, lensesApiUrl, apiKey) {
        this.container = d3.select(`#${containerId}`);
        this.apiUrl = lensesApiUrl;
        this.apiKey = apiKey;
        this.width = 1200;
        this.height = 800;
        this.svg = null;
        this.simulation = null;
    }

    async initialize() {
        // Create SVG canvas
        this.svg = this.container.append('svg')
            .attr('width', this.width)
            .attr('height', this.height)
            .call(d3.zoom().on('zoom', (event) => {
                this.svg.select('g').attr('transform', event.transform);
            }))
            .append('g');

        // Fetch lineage data
        const lineageData = await this.fetchLineageData();

        // Render visualization
        this.render(lineageData);
    }

    async fetchLineageData() {
        const response = await fetch(`${this.apiUrl}/api/v1/kafka/topics/lineage`, {
            headers: {
                'X-Kafka-Lenses-Token': this.apiKey
            }
        });
        return await response.json();
    }

    render(data) {
        // Transform data to nodes and links
        const nodes = this.buildNodes(data);
        const links = this.buildLinks(data);

        // Create force simulation
        this.simulation = d3.forceSimulation(nodes)
            .force('link', d3.forceLink(links).id(d => d.id).distance(100))
            .force('charge', d3.forceManyBody().strength(-300))
            .force('center', d3.forceCenter(this.width / 2, this.height / 2))
            .force('collision', d3.forceCollide().radius(50));

        // Draw links (edges)
        const link = this.svg.append('g')
            .selectAll('line')
            .data(links)
            .enter().append('line')
            .attr('stroke', '#999')
            .attr('stroke-width', d => Math.sqrt(d.messageCount / 1000))
            .attr('stroke-opacity', 0.6)
            .attr('marker-end', 'url(#arrowhead)');

        // Draw nodes
        const node = this.svg.append('g')
            .selectAll('circle')
            .data(nodes)
            .enter().append('circle')
            .attr('r', d => this.getNodeRadius(d))
            .attr('fill', d => this.getNodeColor(d))
            .attr('stroke', '#fff')
            .attr('stroke-width', 2)
            .call(this.drag(this.simulation))
            .on('click', (event, d) => this.showNodeDetails(d))
            .on('mouseover', (event, d) => this.showTooltip(event, d))
            .on('mouseout', () => this.hideTooltip());

        // Add labels
        const label = this.svg.append('g')
            .selectAll('text')
            .data(nodes)
            .enter().append('text')
            .text(d => d.name)
            .attr('font-size', 10)
            .attr('dx', 15)
            .attr('dy', 4);

        // Add arrow markers
        this.svg.append('defs').append('marker')
            .attr('id', 'arrowhead')
            .attr('viewBox', '-0 -5 10 10')
            .attr('refX', 25)
            .attr('refY', 0)
            .attr('orient', 'auto')
            .attr('markerWidth', 8)
            .attr('markerHeight', 8)
            .append('svg:path')
            .attr('d', 'M 0,-5 L 10,0 L 0,5')
            .attr('fill', '#999');

        // Update positions on simulation tick
        this.simulation.on('tick', () => {
            link
                .attr('x1', d => d.source.x)
                .attr('y1', d => d.source.y)
                .attr('x2', d => d.target.x)
                .attr('y2', d => d.target.y);

            node
                .attr('cx', d => d.x)
                .attr('cy', d => d.y);

            label
                .attr('x', d => d.x)
                .attr('y', d => d.y);
        });
    }

    buildNodes(data) {
        const nodes = [];
        const topics = data.topics || [];

        for (const topic of topics) {
            nodes.push({
                id: topic.name,
                name: topic.name,
                type: 'topic',
                messageCount: topic.messageCount || 0,
                partitions: topic.partitions || 0,
                replication: topic.replication || 0,
                sensitivity: topic.sensitivity || 'public',
                domain: topic.domain || 'unknown'
            });
        }

        // Add external systems
        const connectors = data.connectors || [];
        for (const connector of connectors) {
            nodes.push({
                id: connector.name,
                name: connector.name,
                type: connector.type === 'source' ? 'source' : 'sink',
                system: connector.externalSystem
            });
        }

        return nodes;
    }

    buildLinks(data) {
        const links = [];
        const topics = data.topics || [];

        for (const topic of topics) {
            // Upstream links
            for (const upstream of (topic.upstream || [])) {
                links.push({
                    source: upstream,
                    target: topic.name,
                    type: 'dataflow',
                    messageCount: topic.messageCount || 0
                });
            }

            // Downstream links
            for (const downstream of (topic.downstream || [])) {
                links.push({
                    source: topic.name,
                    target: downstream,
                    type: 'dataflow',
                    messageCount: topic.messageCount || 0
                });
            }
        }

        return links;
    }

    getNodeRadius(node) {
        if (node.type === 'topic') {
            return Math.min(Math.max(Math.sqrt(node.messageCount / 100), 10), 40);
        }
        return 15;
    }

    getNodeColor(node) {
        const colors = {
            'topic': '#4CAF50',
            'source': '#2196F3',
            'sink': '#FF9800'
        };

        if (node.type === 'topic' && node.sensitivity === 'pii') {
            return '#F44336'; // Red for PII
        }

        return colors[node.type] || '#999';
    }

    drag(simulation) {
        function dragstarted(event) {
            if (!event.active) simulation.alphaTarget(0.3).restart();
            event.subject.fx = event.subject.x;
            event.subject.fy = event.subject.y;
        }

        function dragged(event) {
            event.subject.fx = event.x;
            event.subject.fy = event.y;
        }

        function dragended(event) {
            if (!event.active) simulation.alphaTarget(0);
            event.subject.fx = null;
            event.subject.fy = null;
        }

        return d3.drag()
            .on('start', dragstarted)
            .on('drag', dragged)
            .on('end', dragended);
    }

    showNodeDetails(node) {
        // Open details panel with node information
        console.log('Selected node:', node);

        // Update details panel (implementation depends on UI framework)
        const detailsPanel = document.getElementById('node-details');
        if (detailsPanel) {
            detailsPanel.innerHTML = `
                <h3>${node.name}</h3>
                <p><strong>Type:</strong> ${node.type}</p>
                ${node.messageCount ? `<p><strong>Messages:</strong> ${node.messageCount.toLocaleString()}</p>` : ''}
                ${node.partitions ? `<p><strong>Partitions:</strong> ${node.partitions}</p>` : ''}
                ${node.sensitivity ? `<p><strong>Sensitivity:</strong> ${node.sensitivity}</p>` : ''}
                ${node.domain ? `<p><strong>Domain:</strong> ${node.domain}</p>` : ''}
            `;
        }
    }

    showTooltip(event, node) {
        const tooltip = d3.select('#tooltip');
        tooltip.transition().duration(200).style('opacity', 0.9);
        tooltip.html(`<strong>${node.name}</strong><br/>${node.type}`)
            .style('left', (event.pageX + 10) + 'px')
            .style('top', (event.pageY - 28) + 'px');
    }

    hideTooltip() {
        d3.select('#tooltip').transition().duration(500).style('opacity', 0);
    }

    applyFilter(filterType, filterValue) {
        // Apply filter to visualization
        const nodes = this.svg.selectAll('circle');

        nodes.style('opacity', d => {
            if (filterType === 'domain' && d.domain !== filterValue) return 0.2;
            if (filterType === 'sensitivity' && d.sensitivity !== filterValue) return 0.2;
            return 1.0;
        });
    }

    exportDiagram(format) {
        switch(format) {
            case 'svg':
                this.exportSVG();
                break;
            case 'png':
                this.exportPNG();
                break;
            case 'json':
                this.exportJSON();
                break;
            case 'graphml':
                this.exportGraphML();
                break;
        }
    }

    exportSVG() {
        const svgData = this.container.select('svg').node().outerHTML;
        const blob = new Blob([svgData], {type: 'image/svg+xml'});
        this.downloadBlob(blob, 'lineage-diagram.svg');
    }

    exportPNG() {
        const svgElement = this.container.select('svg').node();
        const canvas = document.createElement('canvas');
        canvas.width = this.width;
        canvas.height = this.height;
        const ctx = canvas.getContext('2d');

        const svgData = new XMLSerializer().serializeToString(svgElement);
        const img = new Image();
        img.onload = () => {
            ctx.drawImage(img, 0, 0);
            canvas.toBlob(blob => {
                this.downloadBlob(blob, 'lineage-diagram.png');
            });
        };
        img.src = 'data:image/svg+xml;base64,' + btoa(svgData);
    }

    exportJSON() {
        const data = {
            nodes: this.simulation.nodes(),
            links: this.simulation.force('link').links()
        };
        const blob = new Blob([JSON.stringify(data, null, 2)], {type: 'application/json'});
        this.downloadBlob(blob, 'lineage-data.json');
    }

    exportGraphML() {
        // Export in GraphML format for Neo4j import
        const nodes = this.simulation.nodes();
        const links = this.simulation.force('link').links();

        let graphml = '<?xml version="1.0" encoding="UTF-8"?>\n';
        graphml += '<graphml xmlns="http://graphml.graphdrawing.org/xmlns">\n';
        graphml += '  <graph id="G" edgedefault="directed">\n';

        // Add nodes
        for (const node of nodes) {
            graphml += `    <node id="${node.id}">
      <data key="name">${node.name}</data>
      <data key="type">${node.type}</data>
    </node>\n`;
        }

        // Add edges
        for (const link of links) {
            graphml += `    <edge source="${link.source.id}" target="${link.target.id}"/>\n`;
        }

        graphml += '  </graph>\n</graphml>';

        const blob = new Blob([graphml], {type: 'application/xml'});
        this.downloadBlob(blob, 'lineage-graph.graphml');
    }

    downloadBlob(blob, filename) {
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        a.download = filename;
        document.body.appendChild(a);
        a.click();
        document.body.removeChild(a);
        URL.revokeObjectURL(url);
    }
}

// Usage example
const viz = new LineageVisualization(
    'lineage-container',
    'https://lenses.example.com',
    'your-api-key'
);
viz.initialize();
