    def _get_join_type(self, sql: str) -> str:
        if "INNER JOIN" in sql.upper(): return "INNER"
        if "LEFT JOIN" in sql.upper(): return "LEFT"
        if "RIGHT JOIN" in sql.upper(): return "RIGHT"
        return "INNER"

    def _get_join_condition(self, sql: str) -> str:
        if " ON " in sql.upper():
            return sql.upper().split(" ON ")[1].split(" ")[0]
        return "unknown"

    def _extract_agg_field(self, sql: str, func: str) -> str:
        # Extract field from aggregation function
        start = sql.upper().find(func) + len(func)
        end = sql.find(")", start)
        return sql[start+1:end].strip()
